/**
 * The scene description format. Every type here is a plain, JSON-serializable
 * object: a scene can be written by hand, generated by a tool, stored as JSON
 * and passed straight to {@link renderSvg}.
 *
 * Units are scene units; at `zoom: 1` one unit is one SVG pixel.
 * Axes: x right, y down, z toward the viewer. Angles are in degrees.
 */

/**
 * A 3D position or offset. Missing components default to 0, so
 * `{ y: -20 }` means `{ x: 0, y: -20, z: 0 }`.
 */
export interface VectorInput {
  /** Rightward offset. Default 0. */
  x?: number;
  /** Downward offset. Default 0. */
  y?: number;
  /** Offset toward the viewer. Default 0. */
  z?: number;
}

/**
 * Euler angles in degrees, applied about z first, then y, then x.
 * Positive `z` turns clockwise on screen; positive `y` moves the +x side away
 * from the viewer; positive `x` moves the bottom (+y) side toward the viewer.
 */
export interface RotationInput {
  /** Degrees about the x axis. Default 0. */
  x?: number;
  /** Degrees about the y axis. Default 0. */
  y?: number;
  /** Degrees about the z axis. Default 0. */
  z?: number;
}

/** Options shared by every node. */
export interface NodeBase {
  /** Optional name. Used in error messages; not emitted in the SVG. */
  id?: string;
  /** Position relative to the parent. Default `{ x: 0, y: 0, z: 0 }`. */
  translate?: VectorInput;
  /** Rotation relative to the parent, in degrees. Default no rotation. */
  rotate?: RotationInput;
  /**
   * Scale relative to the parent: one number for uniform scale or a vector
   * per axis. Stroke widths scale with the overall size. Default 1.
   */
  scale?: number | VectorInput;
  /** Set to false to hide this node and all of its children. Default true. */
  visible?: boolean;
  /** Child nodes. They inherit this node's translate, rotate and scale. */
  children?: Node[];
}

/** Options shared by every drawable shape. */
export interface ShapeBase extends NodeBase {
  /**
   * Any CSS color: `#rgb`, `#rrggbb`, `#rrggbbaa`, `rgb(...)`, `hsl(...)`,
   * a named color such as `tomato`, or `currentColor`. Default `"#333"`.
   */
  color?: string;
  /**
   * Width of the round-capped outline in scene units. A thick stroke on a
   * single point draws a sphere-like dot; on a line it draws a tube.
   * Use 0 for no outline (then set `fill: true` or nothing is drawn). Default 1.
   */
  stroke?: number;
  /** Fill the inside of the shape with `color`. Default false. */
  fill?: boolean;
  /**
   * What the shape shows from behind, as in Zdog. Its front is the side its
   * local +z axis points to after every transform (local +z for a shape in
   * the local x/y plane). `true` draws it from both sides; `false` leaves it
   * out whenever its front faces away from the viewer, including when it is
   * seen exactly edge-on; a color draws it in that color from behind.
   * Default true.
   *
   * On a sphere's surface, a flat detail with `backface: false` disappears
   * exactly when it turns edge-on, so it never pops in a turning animation.
   */
  backface?: boolean | string;
}

/** An invisible container used to move, rotate and scale its children together. */
export interface GroupNode extends NodeBase {
  type: 'group';
}

/** A cubic Bezier segment from the previous point, through two control points, to an end point. */
export interface BezierInput {
  /** `[control1, control2, end]`. */
  bezier: [VectorInput, VectorInput, VectorInput];
}

/** A point in a path: a straight line to a point, or a Bezier curve. */
export type PathPoint = VectorInput | BezierInput;

/**
 * A round dot at the node's origin, drawn like a sphere. Its diameter is
 * `stroke`. The same as a `path` with the single point `{}`.
 */
export interface DotNode extends NodeBase {
  type: 'dot';
  /** A CSS color. Default `"#333"`. */
  color?: string;
  /** The dot's diameter in scene units. Default 1. */
  stroke?: number;
}

/**
 * A free-form path. One point draws a dot, two points draw a line, more
 * points draw a polyline or polygon. The first entry must be a plain point.
 */
export interface PathNode extends ShapeBase {
  type: 'path';
  /** The points, in local coordinates. At least one. */
  path: PathPoint[];
  /** Connect the last point back to the first. Default false. */
  closed?: boolean;
}

/** An ellipse (or circle) in the local x/y plane, centered on the origin. */
export interface EllipseNode extends ShapeBase {
  type: 'ellipse';
  /** Diameter of a circle. Use this or `width` and `height`. */
  diameter?: number;
  /** Width along x. Use with `height`, instead of `diameter`. */
  width?: number;
  /** Height along y. Use with `width`, instead of `diameter`. */
  height?: number;
}

/** A rectangle in the local x/y plane, centered on the origin. */
export interface RectNode extends ShapeBase {
  type: 'rect';
  /** Width along x. */
  width: number;
  /** Height along y. */
  height: number;
}

/** A regular polygon in the local x/y plane, centered on the origin, with one corner pointing up (-y). */
export interface PolygonNode extends ShapeBase {
  type: 'polygon';
  /** Number of sides, an integer of at least 3. */
  sides: number;
  /** Distance from the center to each corner. */
  radius: number;
}

/**
 * Options shared by the solids: `box`, `cylinder`, `cone` and `hemisphere`.
 *
 * A solid is always filled. With one `color`, each face gets a fixed lighter
 * or darker version of it, chosen by the direction the face points in the
 * scene (not by the view), so the solid reads as 3D without lighting. The
 * face pointing toward the viewer of an unrotated scene, and the round
 * surface of an upright cylinder or cone, keep `color` exactly.
 */
export interface SolidBase extends NodeBase {
  /** Base color of every face. Any CSS color. Default `"#333"`. */
  color?: string;
  /**
   * Width of the round-capped outline drawn around every face in that face's
   * color. It rounds the edges and hides seams between faces. Default 1.
   */
  stroke?: number;
  /** Solids are always filled. Only `true` is accepted. */
  fill?: true;
  /**
   * Give each face a fixed lighter or darker version of `color`. Set to false
   * to paint every face in `color` exactly. Faces with their own color are
   * never shaded. Default true.
   */
  shade?: boolean;
}

/**
 * A box centered on the origin: `width` along x, `height` along y and `depth`
 * along z. Faces: front (+z), rear (-z), left (-x), right (+x), top (-y),
 * bottom (+y).
 */
export interface BoxNode extends SolidBase {
  type: 'box';
  width: number;
  height: number;
  depth: number;
  /** Color of the face toward +z. */
  frontFace?: string;
  /** Color of the face toward -z. */
  rearFace?: string;
  /** Color of the face toward -x. */
  leftFace?: string;
  /** Color of the face toward +x. */
  rightFace?: string;
  /** Color of the face toward -y (up). */
  topFace?: string;
  /** Color of the face toward +y (down). */
  bottomFace?: string;
}

/**
 * A cylinder along the local z axis, centered on the origin, like Zdog's.
 * Use `rotate: { x: 90 }` to stand it up with `frontFace` on top.
 */
export interface CylinderNode extends SolidBase {
  type: 'cylinder';
  /** Diameter of the round ends. */
  diameter: number;
  /** Distance between the ends, along z. */
  length: number;
  /** Color of the end at z = +length / 2. */
  frontFace?: string;
  /** Color of the end at z = -length / 2. */
  backface?: string;
}

/**
 * A cone with its round base at z = 0 and its tip at z = `length`, like
 * Zdog's. Use `rotate: { x: 90 }` to point the tip up.
 */
export interface ConeNode extends SolidBase {
  type: 'cone';
  /** Diameter of the base. */
  diameter: number;
  /** Distance from the base to the tip, along z. */
  length: number;
  /** Color of the flat base. */
  backface?: string;
}

/**
 * Half a sphere with its flat side at z = 0 and its dome toward +z, like
 * Zdog's. Use `rotate: { x: 90 }` to point the dome up.
 */
export interface HemisphereNode extends SolidBase {
  type: 'hemisphere';
  /** Diameter of the sphere. */
  diameter: number;
  /** Color of the flat side. */
  backface?: string;
}

/** Any node that can appear in a scene tree. */
export type Node =
  | GroupNode
  | DotNode
  | PathNode
  | EllipseNode
  | RectNode
  | PolygonNode
  | BoxNode
  | CylinderNode
  | ConeNode
  | HemisphereNode;

/** The `type` values a node can have. */
export type NodeType = Node['type'];

/** A complete scene: the viewport plus the tree of nodes. */
export interface Scene {
  /** Width of the output image in pixels. */
  width: number;
  /** Height of the output image in pixels. */
  height: number;
  /** Multiplies every distance and stroke width. Default 1. */
  zoom?: number;
  /** Background color. Default none (transparent). */
  background?: string;
  /** Accessible title, emitted as `<title>` and `aria-label`. */
  title?: string;
  /**
   * How round things are painted. `"flat"` (default) gives each one a single
   * color. `"soft"` shades dots, thick lines and the round surfaces of
   * solids, as if lit from the upper left; flat shapes stay as they are.
   */
  shading?: 'flat' | 'soft';
  /**
   * View rotation applied to the whole scene, in degrees. For example
   * `{ x: -15 }` looks down on the scene from slightly above.
   */
  rotate?: RotationInput;
  /** Top-level nodes. The scene origin is the center of the image. */
  children: Node[];
}
